class Solution:
    def scoreDifference(self, nums: List[int]) -> int:
        a = b = 0
        active = 0
        for i, x in enumerate(nums):
            if x % 2 == 1: active ^= 1
            if i % 6 == 5: active ^= 1
            if active == 0: a += x
            else: b += x
        return a - b

c.cpp:
class Solution {
public:
    int scoreDifference(vector<int>& nums) {
        long a = 0, b = 0; int active = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] % 2 == 1) active ^= 1;
            if (i % 6 == 5) active ^= 1;
            if (active == 0) a += nums[i]; else b += nums[i];
        }
        return (int)(a - b);
    }
};

